#define DT_DRV_COMPAT zephyr_adc_emul

#include <zephyr/drivers/adc.h>
#include <zephyr/drivers/adc/adc_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/sys/util.h>

LOG_MODULE_REGISTER(adc_emul, CONFIG_ADC_LOG_LEVEL);

#define ADC_CONTEXT_USES_KERNEL_TIMER
#include "adc_context.h"

#define ADC_EMUL_MAX_RESOLUTION 16

/**
 * @brief Channel specific configuration
 *
 *This structure contains configuration of single channel and current
 * method of obtaining samples.
 */
struct adc_emul_chan_cfg {
	/** Pointer to function used to obtain sample value */
	adc_emul_value_func func;
	/** Pointer to data that are passed to @a func on call */
	void *func_data;
	/** Reference voltage source */
	enum adc_reference ref;
	/** Gain value */
	enum adc_gain gain;
	/** Channel ID */
	uint8_t chan_id;
	/**
	 *Flag which informs if raw Value is passed directly to
	 * the output buffer.
	 */
	bool raw_value;
};

/**
 * @brief Emulated ADC data
 *
 * Structure contains data structures used by emulated ADC.
 */
struct adc_emul_data {
	/** Structure that handle state of ongoing read operation */
	struct adc_context ctx;
	/** Pointer to ADC emulator own device structure */
	const struct device *dev;
	/** Pointer to memory where next sample will be written */
	uint16_t *buf;
	/**Pointer to where buffer will be reset in case of repeated sampling */
	uint16_t *repeat_buf;
	/** Mask with channels that will be sampled in current read operation */
	uint32_t channels;
	/**
	 * Array of each channel configuration, size is described by
	 * @a num_channels in @a adc_emul_config
	 */
	struct adc_emul_chan_cfg *chan_cfg;
	/** Thread that performs sampling */
	struct k_thread thread;
	/** Semaphore used to control starting of sampling thread */
	struct k_sem sem;
	/** Mutex used to control access to reference voltage values and
	 * channel configuration
	 */
	struct k_mutex cfg_mtx;
	/** Value of VDD reference voltage in mV */
	uint16_t ref_vdd;
	/** Value of external 0 reference voltage in mV */
	uint16_t ref_ext0;
	/** Value of external 1 reference voltage in mV */
	uint16_t ref_ext1;
	/**Value of internal reference voltage in mV */
	uint16_t ref_int;
	/** Resolution (number of bits) of current read operation */
	uint8_t resolution;

	/** Stack for sampling thread */
	K_KERNEL_STACK_MEMBER(stack,
			CONFIG_ADC_EMUL_ACQUISITION_THREAD_STACK_SIZE);
};

/**
 * @brief Emulated ADC configuration
 *
 * This structure contains constant configuration of ADC emulator
 */
struct adc_emul_config {
	/** Number of supported channels */
	uint8_t num_channels;
};

/**
 * @brief Convert @a ref to reference voltage value in mV
 *
 * @param data Internal data of ADC emulator
 * @param ref Selected reference voltage source
 *
 * @return Reference voltage in mV
 * @return 0 if reference wasn't configured or isn't supported
 */
static uint16_t adc_emul_get_ref_voltage(struct adc_emul_data *data,
					 enum adc_reference ref)
{
	uint16_t voltage;

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	switch (ref) {
	case ADC_REF_VDD_1:
		voltage = data->ref_vdd;
		break;
	case ADC_REF_VDD_1_2:
		voltage = data->ref_vdd / 2;
		break;
	case ADC_REF_VDD_1_3:
		voltage = data->ref_vdd / 3;
		break;
	case ADC_REF_VDD_1_4:
		voltage = data->ref_vdd / 4;
		break;
	case ADC_REF_INTERNAL:
		voltage = data->ref_int;
		break;
	case ADC_REF_EXTERNAL0:
		voltage = data->ref_ext0;
		break;
	case ADC_REF_EXTERNAL1:
		voltage = data->ref_ext1;
		break;
	default:
		voltage = 0;
	}

	k_mutex_unlock(&data->cfg_mtx);

	return voltage;
}

int adc_emul_const_value_set(const struct device *dev, unsigned int chan,
			     uint32_t value)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	struct adc_emul_chan_cfg *chan_cfg;

	if (chan >= config->num_channels) {
		LOG_ERR("unsupported channel %d", chan);
		return -EINVAL;
	}

	chan_cfg = &data->chan_cfg[chan];

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	chan_cfg->func = NULL;
	chan_cfg->func_data = (void *)(uintptr_t)value;
	chan_cfg->raw_value = false;

	k_mutex_unlock(&data->cfg_mtx);

	return 0;
}

int adc_emul_const_raw_value_set(const struct device *dev, unsigned int chan,
				 uint32_t raw_value)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	struct adc_emul_chan_cfg *chan_cfg;

	if (chan >= config->num_channels) {
		LOG_ERR("unsupported channel %d", chan);
		return -EINVAL;
	}

	chan_cfg = &data->chan_cfg[chan];

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	chan_cfg->func = NULL;
	chan_cfg->func_data = (void *)(uintptr_t)raw_value;
	chan_cfg->raw_value = true;

	k_mutex_unlock(&data->cfg_mtx);

	return 0;
}

int adc_emul_value_func_set(const struct device *dev, unsigned int chan,
			    adc_emul_value_func func, void *func_data)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	struct adc_emul_chan_cfg *chan_cfg;

	if (chan >= config->num_channels) {
		LOG_ERR("unsupported channel %d", chan);
		return -EINVAL;
	}

	chan_cfg = &data->chan_cfg[chan];

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	chan_cfg->func = func;
	chan_cfg->func_data = func_data;
	chan_cfg->raw_value = false;

	k_mutex_unlock(&data->cfg_mtx);

	return 0;
}

int adc_emul_raw_value_func_set(const struct device *dev, unsigned int chan,
				adc_emul_value_func func, void *func_data)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	struct adc_emul_chan_cfg *chan_cfg;

	if (chan >= config->num_channels) {
		LOG_ERR("unsupported channel %d", chan);
		return -EINVAL;
	}

	chan_cfg = &data->chan_cfg[chan];

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	chan_cfg->func = func;
	chan_cfg->func_data = func_data;
	chan_cfg->raw_value = true;

	k_mutex_unlock(&data->cfg_mtx);

	return 0;
}

int adc_emul_ref_voltage_set(const struct device *dev, enum adc_reference ref,
			     uint16_t value)
{
	struct adc_emul_data *data = dev->data;
	int err = 0;

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	switch (ref) {
	case ADC_REF_VDD_1:
		data->ref_vdd = value;
		break;
	case ADC_REF_INTERNAL:
		data->ref_int = value;
		break;
	case ADC_REF_EXTERNAL0:
		data->ref_ext0 = value;
		break;
	case ADC_REF_EXTERNAL1:
		data->ref_ext1 = value;
		break;
	default:
		LOG_ERR("unimplemented reference %d", ref);
		err = -EINVAL;
	}

	k_mutex_unlock(&data->cfg_mtx);

	return err;
}

/**
 * @brief Convert input voltage @a val in mV to raw sample value
 *
 * @param data Internal data of ADC emulator
 * @param chan_cfg Configuration of channel which is sampled
 * @param val Input voltage in mV which is converted
 *
 * @return0 on success
 * @return -EINVAL if conversion failed (wrong configuration)
 */
static int adc_emul_convert_value(struct adc_emul_data *data,
				  struct adc_emul_chan_cfg *chan_cfg,
				  uint32_t *val)
{
	uint16_t ref_v;
	uint64_t tmp;
	int err;

	ref_v = adc_emul_get_ref_voltage(data, chan_cfg->ref);
	if (ref_v == 0) {
		LOG_ERR("reference voltage isn't configured (chan %d)",
			chan_cfg->chan_id);
		return -EINVAL;
	}

	/* Multiply by gain */
	err = adc_gain_invert(chan_cfg->gain, val);
	if (err) {
		LOG_ERR("unsupported gain %d in chan %d", chan_cfg->gain,
			chan_cfg->chan_id);
		return -EINVAL;
	}

	/* Check if value isn't bigger than reference voltage, saturate if it is */
	if (*val > ref_v) {
		*val = BIT_MASK(data->resolution);
		return 0;
	}

	/*
	 * Calculate sample value on the basis of equation:
	 * sample =adc_in * (2^resolution - 1) / v_ref
	 * Where adc_in has inverted gain applied.
	 * 64 bits are used to prevent overflow.
	 * Before division,v_ref/2 is added to get Nearest-even rounding
	 */
	tmp = (uint64_t)(*val) * BIT_MASK(data->resolution) + ref_v / 2;
	*val = tmp / ref_v;

	return 0;
}

static int adc_emul_channel_setup(const struct device *dev,
				  const struct adc_channel_cfg *channel_cfg)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	struct adc_emul_chan_cfg *emul_chan_cfg;

	if (channel_cfg->channel_id >= config->num_channels) {
		LOG_ERR("unsupported channel %d", channel_cfg->channel_id);
		return -EINVAL;
	}

	if (channel_cfg->acquisition_time != ADC_ACQ_TIME_DEFAULT) {
		LOG_ERR("unsupported channel acquisition_time %d",
			channel_cfg->acquisition_time);
		return -EINVAL;
	}

	if (channel_cfg->differential) {
		LOG_ERR("Differential channels are not supported");
		return -EINVAL;
	}

	if (adc_emul_get_ref_voltage(data, channel_cfg->reference) == 0) {
		LOG_ERR("Reference voltage wasn't set or isn't supported (%d)",
			channel_cfg->reference);
		return -EINVAL;
	}

	/* Test if gain is supported */
	uint32_t dummy_gain_value = 1;

	if (adc_gain_invert(channel_cfg->gain, &dummy_gain_value)) {
		LOG_ERR("unsupported channel gain %d", channel_cfg->gain);
		return -EINVAL;
	}

	emul_chan_cfg = &data->chan_cfg[channel_cfg->channel_id];

	k_mutex_lock(&data->cfg_mtx, K_FOREVER);

	emul_chan_cfg->gain = channel_cfg->gain;
	emul_chan_cfg->ref = channel_cfg->reference;

	k_mutex_unlock(&data->cfg_mtx);

	return 0;
}

/**
 * @brief Check if buffer in @a sequence is big enough to hold all ADC samples
 *
 * @param dev ADC emulator device
 * @param sequence ADC sequence description
 *
 * @return 0 on success
 * @return -ENOMEM if buffer is not big enough
 */
static int adc_emul_check_buffer_size(const struct device *dev,
					 const struct adc_sequence *sequence)
{
	const struct adc_emul_config *config = dev->config;
	uint8_t channels = 0;
	size_t needed;
	uint32_t mask;

	for (mask = BIT(config->num_channels - 1); mask != 0; mask >>= 1) {
		if (mask & sequence->channels) {
			channels++;
		}
	}

	needed = channels * sizeof(uint16_t);
	if (sequence->options) {
		needed *= (1 + sequence->options->extra_samplings);
	}

	if (sequence->buffer_size < needed) {
		return -ENOMEM;
	}

	return 0;
}

/**
 * @brief Start processing read request
 *
 * @param dev ADC emulator device
 * @param sequence ADC sequence description
 *
 * @return 0 on success
 * @return -EINVAL ifRead parameters aren't valid
 * @return -ENOMEM if buffer is not big enough
 */
static int adc_emul_start_read(const struct device *dev,
			       const struct adc_sequence *sequence)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	int err;

	if (sequence->resolution > ADC_EMUL_MAX_RESOLUTION ||
	    sequence->resolution == 0) {
		LOG_ERR("unsupported resolution %d", sequence->resolution);
		return -EINVAL;
	}

	if (find_msb_set(sequence->channels) > config->num_channels) {
		LOG_ERR("unsupported channels in mask: 0x%08x",
			sequence->channels);
		return -EINVAL;
	}

	if (sequence->calibrate) {
		LOG_ERR("calibration is not supported");
		return -ENOTSUP;
	}

	if (sequence->oversampling) {
		LOG_ERR("oversampling is not supported");
		return -ENOTSUP;
	}

	err = adc_emul_check_buffer_size(dev, sequence);
	if (err) {
		LOG_ERR("buffer size too small");
		return err;
	}

	data->resolution = sequence->resolution;
	data->buf = sequence->buffer;

	adc_context_start_read(&data->ctx, sequence);

	return adc_context_wait_for_completion(&data->ctx);
}

static int adc_emul_read_async(const struct device *dev,
			       const struct adc_sequence *sequence,
			       struct k_poll_signal *async)
{
	struct adc_emul_data *data = dev->data;
	int err;

	adc_context_lock(&data->ctx, async ? true : false, async);
	err = adc_emul_start_read(dev, sequence);
	adc_context_release(&data->ctx, err);

	return err;
}

static int adc_emul_read(const struct device *dev,
			 const struct adc_sequence *sequence)
{
	return adc_emul_read_async(dev, sequence, NULL);
}

static void adc_context_start_sampling(struct adc_context *ctx)
{
	struct adc_emul_data *data =
		CONTAINER_OF(ctx, struct adc_emul_data, ctx);

	data->channels = ctx->sequence.channels;
	data->repeat_buf = data->buf;

	k_sem_give(&data->sem);
}

static void adc_context_update_buffer_pointer(struct adc_context *ctx,
					      bool repeat_sampling)
{
	struct adc_emul_data *data =
		CONTAINER_OF(ctx, struct adc_emul_data, ctx);

	if (repeat_sampling) {
		data->buf = data->repeat_buf;
	}
}

/**
 * @brief Function which runs in sampling thread of ADC emulator
 *
 * Wait on semaphore until sampling is started, then obtain samples for all
 * requested channels. Use configured value function or constant input.
 *
 * @param data_ptr Pointer to adc_emul_data bounded with this thread
 * @param p2 Unused
 * @param p3 Unused
 */
static void adc_emul_acquisition_thread(void *data_ptr, void *p2, void *p3)
{
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	struct adc_emul_data *data = data_ptr;
	struct adc_emul_chan_cfg *chan_cfg;
	uint32_t val;
	int err;

	while (true) {
		k_sem_take(&data->sem, K_FOREVER);

		err = 0;

		while (data->channels) {
			unsigned int chan = find_lsb_set(data->channels) - 1;

			LOG_DBG("reading channel %d", chan);

			chan_cfg = &data->chan_cfg[chan];

			k_mutex_lock(&data->cfg_mtx, K_FOREVER);
			if (chan_cfg->func) {
				err = chan_cfg->func(data->dev, chan,
						     chan_cfg->func_data, &val);
			} else {
				val = (uint32_t)(uintptr_t)chan_cfg->func_data;
			}

			if (err) {
				LOG_ERR("failed to read channel %d (err %d)",
					chan, err);
				k_mutex_unlock(&data->cfg_mtx);
				break;
			}

			if (chan_cfg->raw_value) {
				if (val > BIT_MASK(data->resolution)) {
					LOG_ERR("raw value %d bigger than maximum allowed %lu for resolution %d",
						val, BIT_MASK(data->resolution),
						data->resolution);
					err = -EINVAL;
				}
			} else {
				err = adc_emul_convert_value(data, chan_cfg, &val);
			}

			k_mutex_unlock(&data->cfg_mtx);

			if (err) {
				break;
			}

			LOG_DBG("read channel %d, result = %d", chan, val);

			*data->buf++ = val;
			WRITE_BIT(data->channels, chan, 0);
		}

		adc_context_on_sampling_done(&data->ctx, data->dev);
		if (err) {
			adc_context_complete(&data->ctx, err);
		}
	}
}

/**
 * @brief Function called on init for each ADC emulator device
 *
 * @param dev ADC emulator device
 *
 * @return 0 on success
 */
static int adc_emul_init(const struct device *dev)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	int chan;

	data->dev = dev;

	k_sem_init(&data->sem, 0, 1);
	k_mutex_init(&data->cfg_mtx);
	adc_context_init(&data->ctx);

	for (chan = 0; chan < config->num_channels; chan++) {
		struct adc_emul_chan_cfg *chan_cfg = &data->chan_cfg[chan];

		chan_cfg->func = NULL;
		chan_cfg->func_data = NULL;
		chan_cfg->gain = ADC_GAIN_1;
		chan_cfg->ref = ADC_REF_INTERNAL;
		chan_cfg->chan_id = chan;
		chan_cfg->raw_value = false;
	}

	k_thread_create(&data->thread, data->stack,
			CONFIG_ADC_EMUL_ACQUISITION_THREAD_STACK_SIZE,
			adc_emul_acquisition_thread,
			data, NULL, NULL,
			CONFIG_ADC_EMUL_ACQUISITION_THREAD_PRIO,
			0, K_NO_WAIT);

	adc_context_unlock_unconditionally(&data->ctx);

	return 0;
}

#define ADC_EMUL_INIT(_num)						\
	static DEVICE_API(adc, adc_emul_api_##_num) = {			\
		.channel_setup = adc_emul_channel_setup,		\
		.read = adc_emul_read,					\
		.ref_internal = DT_INST_PROP(_num, ref_internal_mv),	\
		IF_ENABLED(CONFIG_ADC_ASYNC,				\
			   (.read_async = adc_emul_read_async,))	\
	};								\
									\
	static struct adc_emul_chan_cfg					\
		adc_emul_ch_cfg_##_num[DT_INST_PROP(_num, nchannels)];	\
									\
	static const struct adc_emul_config adc_emul_config_##_num = {	\
		.num_channels = DT_INST_PROP(_num, nchannels),		\
	};								\
									\
	static struct adc_emul_data adc_emul_data_##_num = {		\
		ADC_CONTEXT_INIT_TIMER(adc_emul_data_##_num, ctx),	\
		ADC_CONTEXT_INIT_LOCK(adc_emul_data_##_num, ctx),	\
		ADC_CONTEXT_INIT_SYNC(adc_emul_data_##_num, ctx),	\
		.chan_cfg = adc_emul_ch_cfg_##_num,			\
		.ref_vdd = DT_INST_PROP(_num, ref_vdd_mv),		\
		.ref_ext0 = DT_INST_PROP(_num, ref_ext0_mv),		\
		.ref_ext1 = DT_INST_PROP(_num, ref_ext1_mv),		\
		.ref_int = DT_INST_PROP(_num, ref_internal_mv),		\
	};								\
									\
	DEVICE_DT_INST_DEFINE(_num, adc_emul_init, NULL,		\
			      &adc_emul_data_##_num,			\
			      &adc_emul_config_##_num, POST_KERNEL,	\
			      CONFIG_ADC_INIT_PRIORITY,			\
			      &adc_emul_api_##_num);

DT_INST_FOREACH_STATUS_OKAY(ADC_EMUL_INIT)
